// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  interpolateColors,
  Easing,
  random,
} from '../remotionShim';


export type ExpiringTimeProps = Record<string, any>;

const ExpiringTime: React.FC<ExpiringTimeProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 2,
  sunColor = "#FFE87C",
  moonColor = "#F5F5F5",
  clockColor = "#FFFFFF",
  clockOpacity = 0.9,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety base style to prevent CSS transitions
  const baseAnimStyle: React.CSSProperties = { transition: "none" };

  // Timing Logic
  const totalFrames = fps * durationInSeconds;
  
  // Phase 1: Accelerated Time (0% -> 80% of video)
  const phase1End = totalFrames * 0.8;
  const phase1Progress = Math.min(1, Math.max(0, frame / phase1End));
  const acceleratedTime = Easing.inOut(Easing.sin)(phase1Progress);

  // Phase 3: Global Fade Out (90% -> 100% of video)
  const phase3Start = totalFrames * 0.9;
  const fadeOutProgress = Math.max(0, frame - phase3Start) / (totalFrames - phase3Start);
  const globalOpacity = interpolate(fadeOutProgress, [0, 1], [1, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Celestial Body Path & Transforming Styling (Sun turning into Moon)
  const celestialX = interpolate(acceleratedTime, [0, 1], [width * 0.15, width * 0.85]);
  const celestialY = interpolate(acceleratedTime, [0, 0.5, 1], [height * 0.35, height * 0.15, height * 0.35]);
  const celestialScale = interpolate(acceleratedTime, [0, 0.5, 1], [1, 1.3, 0.9]);
  
  const celestialColor = interpolateColors(
    acceleratedTime,
    [0, 0.4, 0.6, 1],
    [sunColor, "#FF8C00", "#B0C4DE", moonColor]
  );
  const celestialGlowRadius = interpolate(acceleratedTime, [0, 0.5, 1], [40, 80, 20]);
  const celestialGlowSpread = interpolate(acceleratedTime, [0, 0.5, 1], [20, 40, 10]);

  // Clock Timing & Hands (Synchronized to exactly end at 12:00 Midnight)
  const hoursPassed = interpolate(acceleratedTime, [0, 1], [0, 10]); 
  const currentHourExact = 14 + hoursPassed; // 14:00 (2 PM) -> 24:00 (12 AM)
  const hourAngle = (currentHourExact / 12) * 360;
  const minuteAngle = (currentHourExact % 1) * 360;

  // Second hand independent relentless spin -> limited to 20 rotations to avoid strobing at 2s duration
  const secondHandAngle = interpolate(
    phase1Progress,
    [0, 1],
    [0, 20 * 360],
    { easing: Easing.in(Easing.quad) }
  );

  // Aggressive Shaking Logic right before deadline
  const shakeIntensity = interpolate(
    acceleratedTime,
    [0.7, 0.98, 1],
    [0, 15, 0], // Peaks then completely snaps still at midnight
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const shakeX = shakeIntensity > 0 ? (random(`shakeX-${frame}`) - 0.5) * shakeIntensity : 0;
  const shakeY = shakeIntensity > 0 ? (random(`shakeY-${frame}`) - 0.5) * shakeIntensity : 0;

  // Dynamic Stretching Shadows mapping from Celestial Position
  const shadowX = interpolate(acceleratedTime, [0, 1], [30, -30]);
  const shadowY = interpolate(acceleratedTime, [0, 0.5, 1], [10, 30, 10]);
  const shadowOpacity = interpolate(acceleratedTime, [0, 0.5, 1], [0.3, 0.6, 0.3]);
  const shadowBlur = interpolate(acceleratedTime, [0, 0.5, 1], [15, 25, 15]);
  const clockFilter = `drop-shadow(${shadowX}px ${shadowY}px ${shadowBlur}px rgba(0,0,0,${shadowOpacity}))`;

  const clockSize = Math.min(width, height) * 0.7;
  const clockScale = interpolate(acceleratedTime, [0, 1], [1, 1.15]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill style={{ opacity: globalOpacity, ...baseAnimStyle }}>
        
        {/* Transforming Celestial Body (Sun -> Moon) */}
        <div
          style={{
            position: "absolute",
            left: celestialX,
            top: celestialY,
            width: 120,
            height: 120,
            borderRadius: "50%",
            backgroundColor: celestialColor,
            transform: `translate(-50%, -50%) scale(${celestialScale})`,
            boxShadow: `0 0 ${celestialGlowRadius}px ${celestialGlowSpread}px ${celestialColor}`,
            ...baseAnimStyle,
          }}
        />

        {/* Relentless Analog Clock */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: clockSize,
            height: clockSize,
            transform: `translate(calc(-50% + ${shakeX}px), calc(-50% + ${shakeY}px)) scale(${clockScale})`,
            borderRadius: "50%",
            border: `6px solid ${clockColor}`,
            opacity: clockOpacity,
            filter: clockFilter,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            ...baseAnimStyle,
          }}
        />
        
        {/* Clock Internals (Rendered outside filter container to avoid nested transforms breaking) */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: clockSize,
            height: clockSize,
            transform: `translate(calc(-50% + ${shakeX}px), calc(-50% + ${shakeY}px)) scale(${clockScale})`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            opacity: clockOpacity,
            ...baseAnimStyle,
          }}
        >
          {/* Dial Marks */}
          {[...Array(12)].map((_, i) => (
            <div
              key={i}
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
                transform: `rotate(${i * 30}deg)`,
                ...baseAnimStyle,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  top: 8,
                  left: "calc(50% - 3px)",
                  width: 6,
                  height: i % 3 === 0 ? 24 : 12,
                  backgroundColor: clockColor,
                  opacity: 0.8,
                  borderRadius: 3,
                  ...baseAnimStyle,
                }}
              />
            </div>
          ))}

          {/* Center Dot */}
          <div
            style={{
              position: "absolute",
              width: 16,
              height: 16,
              borderRadius: "50%",
              backgroundColor: clockColor,
              zIndex: 10,
              ...baseAnimStyle,
            }}
          />

          {/* Hour Hand */}
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: "calc(50% - 4px)",
              width: 8,
              height: "25%",
              backgroundColor: clockColor,
              transformOrigin: "bottom center",
              transform: `rotate(${hourAngle}deg)`,
              borderRadius: 4,
              ...baseAnimStyle,
            }}
          />

          {/* Minute Hand */}
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: "calc(50% - 3px)",
              width: 6,
              height: "40%",
              backgroundColor: clockColor,
              transformOrigin: "bottom center",
              transform: `rotate(${minuteAngle}deg)`,
              borderRadius: 3,
              ...baseAnimStyle,
            }}
          />

          {/* Rapid Second Hand */}
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: "calc(50% - 1.5px)",
              width: 3,
              height: "45%",
              backgroundColor: "#E74C3C",
              transformOrigin: "bottom center",
              transform: `rotate(${secondHandAngle}deg)`,
              borderRadius: 2,
              ...baseAnimStyle,
            }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ExpiringTime;